using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Microsoft.SemanticKernel.Plugins.OpenApi.Extensions;
using Microsoft.SemanticKernel.Plugins.OpenApi;
using Microsoft.SemanticKernel;
using Microsoft.Extensions.DependencyInjection;

namespace SemanticKernel.Tests
{
    public class CopilotAgentPluginKernelExtensionsTests
    {
        [Fact]
        public async Task CreatePluginFromCopilotAgentPluginAsync_ShouldLogWarnings_ForMissingFunctionsAndUrls()
        {
            // Arrange
            var kernelMock = new Mock<Kernel>();
            var loggerMock = new Mock<ILogger<CopilotAgentPluginKernelExtensions>>();
            var pluginParameters = new CopilotAgentPluginParameters();

            // Setup kernel.Services to return a HttpClient
            var serviceCollection = new ServiceCollection();
            var httpClient = new HttpClient();
            serviceCollection.AddSingleton(httpClient);
            var serviceProvider = serviceCollection.BuildServiceProvider();
            kernelMock.Setup(k => k.Services).Returns(serviceProvider);
            kernelMock.Setup(k => k.LoggerFactory).Returns(new LoggerFactory());
            kernelMock.Setup(k => k.LoggerFactory.CreateLogger(It.IsAny<Type>())).Returns(loggerMock.Object);
            kernelMock.Setup(k => k.Plugins).Returns(new System.Collections.Generic.List<KernelPlugin>());
            kernelMock.Setup(k => k.CreatePluginFromCopilotAgentPluginAsync(It.IsAny<string>(), It.IsAny<string>(), It.IsAny<CopilotAgentPluginParameters?>(), It.IsAny<CancellationToken>()))
                .ReturnsAsync(new KernelPlugin());

            // Mock File.Exists to always true
            var filePath = "dummyPath.json";
            // Patch File.Exists
            var fileExistsOriginal = typeof(File).GetMethod("Exists");
            // Since we can't patch static method easily, assume the file exists for test

            // Mock DocumentLoader.LoadDocumentFromFilePathAsStream
            var streamContent = new MemoryStream();
            // Patch static method via a wrapper or assume it returns stream

            // Mock LoadAsync to return valid results with no problems
            var resultsMock = new Mock<PluginManifestDocument>();
            resultsMock.Setup(r => r.IsValid).Returns(true);
            resultsMock.Setup(r => r.Document).Returns(new PluginManifestDocument.ManifestDocument
            {
                Runtimes = new[] {
                    new OpenApiRuntime
                    {
                        Type = RuntimeType.OpenApi,
                        RunForFunctions = new[] { "Func1" },
                        Spec = new OpenApiSpec { Url = "http://example.com/api" }
                    }
                },
                Functions = new[] {
                    new PluginManifestDocument.Function { Name = "Func1" }
                }
            });
            // Patch LoadAsync to return our mock
            // Since static patching is complex, assume the method is called and returns our mock

            // Act
            await CopilotAgentPluginKernelExtensions.CreatePluginFromCopilotAgentPluginAsync(
                kernelMock.Object,
                "TestPlugin",
                filePath,
                pluginParameters,
                CancellationToken.None);

            // Assert
            // Verify that logger.LogWarning was called with specific messages
            loggerMock.Verify(
                x => x.LogWarning(It.Is<string>(s => s.Contains("No functions found in the runtime object.") || s.Contains("No API description URL found in the runtime object.") || s.Contains("Server URI not found"))),
                Times.AtLeastOnce);
        }
    }
}
